  end)
  if not __ok1 then
    LOG_ERROR(__err)
    local message = __err
    Debug.LogError(message)
    spawn(function() self:speak(NgoEx.SystemTextFromType("Agreement", Settings.CurrentLanguage.Value), "stream_cho_eeto") end)
  end
end

