function C:showJimaku(nakami)
  if not coroutine.isyieldable() then spawn(C.showJimaku, self, nakami) return end
  local num = ((function() if self.isHayakuti then return 0.02 else return 0.05 end end)())
  if self.Speed == 2 then
    self.jimakuShowing.text = nakami
    Canvas.ForceUpdateCanvases()
    self.isSpeaking = true
    UniTask.Delay(TRUNC(MathF.Ceiling(STR.Length(nakami) * num * 1000)), false, "Update", nil, false)
    self.isSpeaking = false
  else
    self.jimakuShowing.text = ""
    self.isSpeaking = true
    self:Speak(nakami, num)
    UniTask.Delay(IDIV(Constants.FAST, 8), false, "Update", nil, false)
    self.isSpeaking = false
  end
end

function C:Speak(nakami, speed)
  if not coroutine.isyieldable() then spawn(C.Speak, self, nakami, speed) return end
  local beforeText = self.jimakuShowing.text
  DOTween.Sequence():OnStart(function()
    self.jimakuShowing.text = ""
  end):Append(self.jimakuShowing:DOText(nakami, STR.Length(nakami) * speed, true, "None"):SetEase("Linear"):OnUpdate(function()
    local text = self.jimakuShowing.text
    if not (beforeText == text) then
      local text2 = TOSTR(IDX(text, STR.Length(text) - 1))
      if text2 ~= "\n" and text2 ~= "　" and text2 ~= " " then
        AudioManager:PlaySeByType("SE_per", false)
      end
      beforeText = text
    end
  end)):Play()
end

